import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"CephFS for Ceph Developer Summit - Vampire","description":"","frontmatter":{"title":"CephFS for Ceph Developer Summit - Vampire","date":"2026-08-14T00:00:00.000Z","updated":"2026-08-15T00:00:00.000Z","tags":["CephFS","MDS","性能优化","会议纪要","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/CephFS_for_Ceph_Developer_Summit_-_Vampire.md","filePath":"posts/2026/CephFS_for_Ceph_Developer_Summit_-_Vampire.md","lastUpdated":null}'),o={name:"posts/2026/CephFS_for_Ceph_Developer_Summit_-_Vampire.md"};function t(n,e,u,s,h,c){return l(),i("div",null,[...e[0]||(e[0]=[r('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次会议是 Ceph Developer Summit（Vampire 版本）的 CephFS 专题会议，由 Venky 主持，涵盖了多个针对 Vampire 版本及后续版本的特性开发与优化议题。</p><h2 id="议题一-元数据-io-子卷-metrics-igor-ibm" tabindex="-1">议题一：元数据 IO 子卷 Metrics（Igor / IBM） <a class="header-anchor" href="#议题一-元数据-io-子卷-metrics-igor-ibm" aria-label="Permalink to &quot;议题一：元数据 IO 子卷 Metrics（Igor / IBM）&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>当前已为数据路径实现了 subvolume metrics，但尚未覆盖元数据 IO 路径。在观测到大量来自 subvolume 的重度元数据 IO 会对 MDS 造成显著压力后，Igor 提出为元数据 IO 实现相同的 metrics 机制。</p><h3 id="技术方案" tabindex="-1">技术方案 <a class="header-anchor" href="#技术方案" aria-label="Permalink to &quot;技术方案&quot;">​</a></h3><ul><li>现有数据 IO metrics 在客户端按 subvolume 聚合，通过滑动窗口机制周期性推送至 MDS，推送后客户端重置本地统计</li><li>元数据 IO metrics 的识别（subvolume 路径归属）已在客户端实现，无需修改 cap 协议</li><li>Greg 提出：与数据 IO 不同，MDS 可直接追踪入向请求并归属到客户端，因此 metadata metrics 的聚合可能直接在 MDS 侧完成，无需客户端额外修改</li></ul><h3 id="决定与后续" tabindex="-1">决定与后续 <a class="header-anchor" href="#决定与后续" aria-label="Permalink to &quot;决定与后续&quot;">​</a></h3><ul><li>技术实现模式与数据 IO metrics 一致，作为现有功能的增强扩展</li><li>后续将更新 tracker，明确需收集的具体 metrics 字段</li><li>此特性有助于监控、调试及元数据密集型 workload 的诊断</li></ul><h2 id="议题二-用户空间客户端性能优化-edwin-venky" tabindex="-1">议题二：用户空间客户端性能优化（Edwin / Venky） <a class="header-anchor" href="#议题二-用户空间客户端性能优化-edwin-venky" aria-label="Permalink to &quot;议题二：用户空间客户端性能优化（Edwin / Venky）&quot;">​</a></h2><h3 id="客户端锁优化" tabindex="-1">客户端锁优化 <a class="header-anchor" href="#客户端锁优化" aria-label="Permalink to &quot;客户端锁优化&quot;">​</a></h3><p>当前 libcephfs 客户端存在一个全局 client lock，其串行化特性是客户端侧的性能瓶颈。优化方向：</p><p><strong>阶段一（已有 PR）：</strong> 将 ObjectCacher 拆分为独立的 mutex</p><ul><li>仅在变更 client 对象自身状态时持有 client lock</li><li>ObjectCacher 使用独立锁保护自身状态，提升并行度</li><li>测试结果：读性能提升约 <strong>30%</strong>，写性能略低于此数值</li><li>注意：需仔细审查锁的获取顺序，避免 sequence number 重排序等边界情况</li></ul><p><strong>阶段二（POC 阶段，尚无 PR）：</strong> 引入 inode lock</p><ul><li>client lock 仅保护 session 等 client 自身状态变更</li><li>通过 inode lock 保护 inode 级操作，允许对不同 inode 的 IO 真正并行</li><li>测试结果：写性能提升约 <strong>70%</strong></li><li>此阶段变更量大，需解决的 ordering 问题更复杂，计划在阶段一合并后推进</li></ul><h3 id="mds-侧性能问题" tabindex="-1">MDS 侧性能问题 <a class="header-anchor" href="#mds-侧性能问题" aria-label="Permalink to &quot;MDS 侧性能问题&quot;">​</a></h3><p><strong>Fair Mutex 问题：</strong></p><ul><li>MDS 使用的 fair mutex 本质上是 ticket lock，锁释放时会唤醒所有等待线程，仅持有下一个 ticket 的线程能获锁，其余线程重新等待，造成 thundering herd</li><li>用标准 mutex 替换后 MDS 性能提升约 <strong>15%</strong></li><li>引入 fair mutex 的背景：早期 MD log 反复抢锁导致客户端 IO 饥饿，fair mutex 解决了公平性但引入了唤醒开销</li><li>下一步：研发基于队列的 mutex 实现，兼顾公平性与性能</li></ul><p><strong>Cache 管理持锁问题：</strong></p><ul><li>MDS 的 cache management 在持有 MDS lock 的情况下进行大块操作，阻塞 dispatcher、finisher、cache 三个线程的并发</li><li>潜在方向：缩短 cache 管理持锁时间，引入优先级队列（前台 IO 与后台 cache 管理分离）</li></ul><h3 id="rados-fsync-提案-greg" tabindex="-1">RADOS fsync 提案（Greg） <a class="header-anchor" href="#rados-fsync-提案-greg" aria-label="Permalink to &quot;RADOS fsync 提案（Greg）&quot;">​</a></h3><p>针对 NFS-Ganesha 客户端的特殊问题：</p><ul><li>Ganesha 及使用 O_DIRECT 的 NFS kernel client 在每次 write syscall 后触发 fsync，导致大量 cap flush 请求集中打到 MDS</li><li>Greg 提出 RADOS fsync：将 write 操作涉及的元数据（mtime、file size、change attribute）直接 flush 到 RADOS data objects，在这些元数据为唯一 dirty 元数据的场景下绕过 MDS</li><li>预期效果：大幅减少 Ganesha 的 cap 流量，解除 IO 在 MDS 上的串行化</li><li>计划在接下来几周内提交 PR</li></ul><p>另一问题：NFSv4 客户端在每次 write 后还会通过 stat 获取最新的 change attribute（inode change attr），多写入场景下需要 cap round trip。初步设想在 RADOS object 内维护 change attribute，避免集中在 MDS，但实现较复杂。</p><h2 id="议题三-普通目录迁移为-subvolume-rishabh-kotresh" tabindex="-1">议题三：普通目录迁移为 Subvolume（Rishabh / Kotresh） <a class="header-anchor" href="#议题三-普通目录迁移为-subvolume-rishabh-kotresh" aria-label="Permalink to &quot;议题三：普通目录迁移为 Subvolume（Rishabh / Kotresh）&quot;">​</a></h2><h3 id="背景-1" tabindex="-1">背景 <a class="header-anchor" href="#背景-1" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>部分 CephFS 用户在不了解 subvolume 抽象的情况下，自行构建了类似的目录结构及挂载方案，现希望能平滑迁移至标准 subvolume 管理体系。</p><h3 id="方案探索" tabindex="-1">方案探索 <a class="header-anchor" href="#方案探索" aria-label="Permalink to &quot;方案探索&quot;">​</a></h3><ul><li><strong>符号链接（symlink）方案</strong>：测试发现问题较多，不够透明（挂载时无法直接挂载 symlink），基本排除</li><li><strong>自定义路径方案</strong>：在 subvolume 元数据文件中记录自定义路径，操作时透明转换 <ul><li>需修改 <code>fs authorize</code> 命令以支持&quot;迁移型 subvolume&quot;的 cap 授权</li><li>迁移型 subvolume 的实际数据路径与标准 subvolume 不同</li></ul></li></ul><h3 id="主要挑战" tabindex="-1">主要挑战 <a class="header-anchor" href="#主要挑战" aria-label="Permalink to &quot;主要挑战&quot;">​</a></h3><ul><li>用户自建目录可能有独立的 pool namespace 及 layout，跨 namespace 数据迁移代价高昂</li><li>当前仍处于早期探索阶段，正在 V2 subvolume 上验证小 patch</li></ul><h3 id="与-v3-subvolume-的关联" tabindex="-1">与 V3 Subvolume 的关联 <a class="header-anchor" href="#与-v3-subvolume-的关联" aria-label="Permalink to &quot;与 V3 Subvolume 的关联&quot;">​</a></h3><ul><li>V3 subvolume 计划支持透明升级（包括挂载中客户端在线升级），目标版本为 Vampire</li><li>V3 升级路径正在开发中，预计下周中完成</li><li>相关 PR 已提交，将链接至 tracker</li></ul><h2 id="议题四-mds-journal-replay-内存优化-daria" tabindex="-1">议题四：MDS Journal Replay 内存优化（Daria） <a class="header-anchor" href="#议题四-mds-journal-replay-内存优化-daria" aria-label="Permalink to &quot;议题四：MDS Journal Replay 内存优化（Daria）&quot;">​</a></h2><h3 id="问题描述" tabindex="-1">问题描述 <a class="header-anchor" href="#问题描述" aria-label="Permalink to &quot;问题描述&quot;">​</a></h3><p>在处理一个 unflushed journal 超过 1TB 的集群时，发现 MDS 在 journal replay 过程中内存消耗极高（RSS 峰值达 600 GB），最终被 OOM killed，不得不使用离线 journal 工具分批处理。</p><p>根本原因：journal event 解码时存在大量浅拷贝（shallow copy），导致来自 messenger 层的 raw buffer 被长期 pin 在内存中。</p><h3 id="关键发现" tabindex="-1">关键发现 <a class="header-anchor" href="#关键发现" aria-label="Permalink to &quot;关键发现&quot;">​</a></h3><ul><li>在单次测试中，超过 <strong>50%</strong> 的 event 总大小由名为 <code>enbl</code>（dentry buffer list）的单一 buffer list 占用</li><li>此 buffer list 在所有 events 解码完成前始终保持引用，不释放</li><li>根源结构为 <strong>D lump</strong>（包含 D full、D remote、D null 三个子结构），存在于每个 journal object 中</li><li>Buffer list 默认使用浅拷贝以避免内存膨胀，但此处反而造成了内存 pin 住不释放的问题</li></ul><h3 id="影响范围" tabindex="-1">影响范围 <a class="header-anchor" href="#影响范围" aria-label="Permalink to &quot;影响范围&quot;">​</a></h3><ul><li>离线 journal 工具（已有批量处理 event split 功能）</li><li><strong>MDS standby-replay</strong>：同样存在内存膨胀问题，active MDS 无此问题</li><li>MDS 从 up:replay 状态恢复到 active 状态的过程</li></ul><h3 id="方案讨论" tabindex="-1">方案讨论 <a class="header-anchor" href="#方案讨论" aria-label="Permalink to &quot;方案讨论&quot;">​</a></h3><ul><li>核心思路：对 D lump 相关 buffer list 改为深拷贝（deep copy），及时释放 messenger 层的 raw buffer</li><li>代价：深拷贝引入额外 CPU 开销，可能影响 MDS replay 速度</li><li>理论收益：RSS 降低约 <strong>25%</strong>（基于估算）</li><li>结论：需实现后进行实测，权衡内存收益与 CPU 开销；目标争取进入 Vampire 版本</li></ul><h2 id="议题五-后续版本特性预告-juba-clyso-由-venky-代为介绍" tabindex="-1">议题五：后续版本特性预告（Juba / Clyso，由 Venky 代为介绍） <a class="header-anchor" href="#议题五-后续版本特性预告-juba-clyso-由-venky-代为介绍" aria-label="Permalink to &quot;议题五：后续版本特性预告（Juba / Clyso，由 Venky 代为介绍）&quot;">​</a></h2><h3 id="gmds-journal-优化与分布机制改进-tracker-407" tabindex="-1">GMDS Journal 优化与分布机制改进（Tracker #407） <a class="header-anchor" href="#gmds-journal-优化与分布机制改进-tracker-407" aria-label="Permalink to &quot;GMDS Journal 优化与分布机制改进（Tracker #407）&quot;">​</a></h3><ul><li>基于 Shangyan 早期未合并的 patch（已在国内部分生产环境运行验证）</li><li>Juba 计划在其基础上完善代码注释、补充文档后提交</li><li>核心改动：<strong>从 MDS journal 中移除 sub-tree map</strong>，减少 log event 数量及解码开销</li><li>预期效果：MDS replay 速度显著提升（sub-tree map journal event 数量减少）</li><li>目标版本：Vampire 之后的 W 版本</li></ul><h3 id="inotify-类似功能-tracker-995" tabindex="-1">inotify 类似功能（Tracker #995） <a class="header-anchor" href="#inotify-类似功能-tracker-995" aria-label="Permalink to &quot;inotify 类似功能（Tracker #995）&quot;">​</a></h3><ul><li>用户对 inotify 支持存在约 10 年历史的需求</li><li>初始提案涉及 MDS 与 sub-manager 之间的 RPC 通信，Venky 和 Greg 认为 sub-manager 扩展性问题使此路径不可行</li><li>当前已有替代设计方案（见 tracker），仍在设计讨论阶段</li></ul><h3 id="subvolume-snapshot-rollback-优化" tabindex="-1">Subvolume Snapshot Rollback 优化 <a class="header-anchor" href="#subvolume-snapshot-rollback-优化" aria-label="Permalink to &quot;Subvolume Snapshot Rollback 优化&quot;">​</a></h3><ul><li>现有 rollback 为全量数据拷贝，Venky 与 Patrick 提出设计方案实现原子性 rollback</li><li>目标版本：Vampire 之后</li></ul><h3 id="零停机升级-zero-downtime-upgrades" tabindex="-1">零停机升级（Zero Downtime Upgrades） <a class="header-anchor" href="#零停机升级-zero-downtime-upgrades" aria-label="Permalink to &quot;零停机升级（Zero Downtime Upgrades）&quot;">​</a></h3><ul><li>当前升级流程要求使用 <code>fs fail</code> 或将 max_mds 缩减至 1，存在可用性影响</li><li>Patrick 和 Igor 分别提出了设计方案</li><li>目标版本：Vampire 之后，相关 tracker 已链接</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本次会议重点围绕 CephFS 的性能优化展开，包括客户端锁粒度细化（30%~70% 读写性能提升）、MDS fair mutex 改进（15% 性能提升）、Ganesha cap 流量优化，以及 MDS journal replay 内存优化（预期降低 RSS 约 25%）。此外，Subvolume V3 升级路径、目录迁移为 subvolume、以及多个面向 W 版本的长期特性（journal 优化、inotify、zero downtime upgrade）也进行了充分讨论，为后续开发明确了方向。</p>',55)])])}const p=a(o,[["render",t]]);export{m as __pageData,p as default};
